pub fn time2str(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_days = Val::from(0);
    let mut l_hours = Val::from(0);
    let mut l_minutes = Val::from(0);
    let mut l_time_left = Val::from(0);
    let mut l_time_s = Val::from("");
    l_time_left = (runtime::arg(&args, 0, Val::from(0)).try_sub(ctx.call(Function::GetTimeTick, vec![Val::from(2)])?)?);
    l_days = (l_time_left.clone().try_div(Val::from(86400))?);
    l_time_left = (l_time_left.clone().try_sub((l_days.clone().try_mul(Val::from(86400))?))?);
    l_hours = (l_time_left.clone().try_div(Val::from(3600))?);
    l_time_left = (l_time_left.clone().try_sub((l_hours.clone().try_mul(Val::from(3600))?))?);
    l_minutes = (l_time_left.clone().try_div(Val::from(60))?);
    l_time_left = (l_time_left.clone().try_sub((l_minutes.clone().try_mul(Val::from(60))?))?);
    l_time_s = Val::from("");
    if l_days.clone().number()? > 1 {
        l_time_s = ((l_time_s.clone() + l_days.clone()) + Val::from(" days, "));
    } else {
        if l_days.clone().number()? > 0 {
            l_time_s = ((l_time_s.clone() + l_days.clone()) + Val::from(" day, "));
        }
    }
    if l_hours.clone().number()? > 1 {
        l_time_s = ((l_time_s.clone() + l_hours.clone()) + Val::from(" hours, "));
    } else {
        if l_hours.clone().number()? > 0 {
            l_time_s = ((l_time_s.clone() + l_hours.clone()) + Val::from(" hour, "));
        }
    }
    if l_minutes.clone().number()? > 1 {
        l_time_s = ((l_time_s.clone() + l_minutes.clone()) + Val::from(" minutes, "));
    } else {
        if l_minutes.clone().number()? > 0 {
            l_time_s = ((l_time_s.clone() + l_minutes.clone()) + Val::from(" minute, "));
        }
    }
    if (l_time_left.clone().number()? > 1 || l_time_left.clone() == 0) {
        l_time_s = ((l_time_s.clone() + l_time_left.clone()) + Val::from(" seconds"));
    } else {
        if l_time_left.clone() == 1 {
            l_time_s = ((l_time_s.clone() + l_time_left.clone()) + Val::from(" second"));
        }
    }
    return Ok(l_time_s.clone());
}
